<?php
declare(strict_types=1);
namespace Norda;

final class Problem extends \RuntimeException { public int $status; public function __construct(string $message,int $status=400){parent::__construct($message);$this->status=$status;} }
function fail(string $message,int $status=400): never { throw new Problem($message,$status); }
function privateDir(): string {
    $dir=getenv('NORDA_DATA_DIR') ?: dirname(__DIR__,3).'/norda-private';
    if(!is_dir($dir)&&!@mkdir($dir,0700,true))fail('Şəxsi məlumat qovluğu yaradıla bilmədi. Hosting dəstəyi ilə əlaqə saxlayın.',503);
    $real=realpath($dir);$public=realpath(dirname(__DIR__,2));
    if(!$real||($public&&str_starts_with(str_replace('\\','/',$real).'/',str_replace('\\','/',$public).'/')))fail('Məlumat qovluğu saytın açıq qovluğundan kənarda olmalıdır.',503);
    return $real;
}
function config(): ?array { $dir=getenv('NORDA_DATA_DIR') ?: dirname(__DIR__,3).'/norda-private';$f=$dir.'/config.php';if(!is_file($f))return null;privateDir();return require $f; }
function seed(): array { static $s;return $s??=json_decode(file_get_contents(__DIR__.'/seed.json'),true,512,JSON_THROW_ON_ERROR); }
function json(array $data,int $status=200): never { http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG);exit; }
function body(int $max=1200000): array { $raw=file_get_contents('php://input');if(strlen($raw)>$max)fail('Sorğu çox böyükdür.',413);try{$d=json_decode($raw,true,128,JSON_THROW_ON_ERROR);}catch(\Throwable){fail('JSON məlumatı düzgün deyil.');}if(!is_array($d))fail('Məlumat düzgün deyil.');return $d; }
function session(): void {
    if(session_status()===PHP_SESSION_ACTIVE)return;
    ini_set('session.use_strict_mode','1');ini_set('session.use_only_cookies','1');
    $save=privateDir().'/sessions';if(!is_dir($save))mkdir($save,0700,true);session_save_path($save);
    session_name('norda_session');session_set_cookie_params(['lifetime'=>0,'path'=>'/','secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','httponly'=>true,'samesite'=>'Strict']);session_start();
    $_SESSION['csrf']??=bin2hex(random_bytes(32));
}
function csrf(): void {session();$t=$_SERVER['HTTP_X_CSRF_TOKEN']??'';if(!is_string($t)||!hash_equals($_SESSION['csrf'],$t))fail('Sessiya yenilənməlidir. Səhifəni yeniləyin.',403);sameOrigin();}
function sameOrigin(): void {if(empty($_SERVER['HTTP_ORIGIN']))return;$origin=parse_url($_SERVER['HTTP_ORIGIN']);$host=$origin['host']??'';if(isset($origin['port']))$host.=':'.$origin['port'];if(strtolower($host)!==strtolower($_SERVER['HTTP_HOST']??''))fail('Sorğunun mənbəyi qəbul edilmir.',403);}
function db(): \PDO {static $pdo;if($pdo)return $pdo;$c=config();if(!$c)fail('Panel hələ quraşdırılmayıb.',503);$pdo=new \PDO($c['dsn'],$c['db_user']??null,$c['db_password']??null,[\PDO::ATTR_ERRMODE=>\PDO::ERRMODE_EXCEPTION,\PDO::ATTR_DEFAULT_FETCH_MODE=>\PDO::FETCH_ASSOC]);if(str_starts_with($c['dsn'],'sqlite:')){$pdo->exec('PRAGMA busy_timeout=5000');$pdo->exec('PRAGMA foreign_keys=ON');}return $pdo;}
function query(string $sql,array $params=[]): \PDOStatement {$s=db()->prepare($sql);$s->execute($params);return $s;}
function user(): array {session();$id=$_SESSION['uid']??null;if(!$id)fail('Daxil olun.',401);$u=query('SELECT id,email,name,role,disabled FROM users WHERE id=?',[$id])->fetch();if(!$u||$u['disabled']){unset($_SESSION['uid']);fail('Giriş bağlıdır.',401);}if(time()-($_SESSION['last']??0)>1800){unset($_SESSION['uid']);fail('Sessiya bitib. Yenidən daxil olun.',401);}$_SESSION['last']=time();return $u;}
function role(array $roles): array {$u=user();if(!in_array($u['role'],$roles,true))fail('Bu əməliyyat üçün icazəniz yoxdur.',403);return $u;}
function can(string $kind,bool $publish=false): array {$u=user();$roles=in_array($kind,['request','quote','customer'],true)?['owner','sales']:['owner','editor'];if($kind==='supplier'||$publish)$roles=['owner'];if(!in_array($u['role'],$roles,true))fail('Bu bölmə üçün icazəniz yoxdur.',403);return $u;}
function now(): string {return gmdate('Y-m-d H:i:s');}
function uuid(): string {return bin2hex(random_bytes(16));}
function text(mixed $v,int $max=1000): string {if(!is_string($v))fail('Mətn sahəsi düzgün deyil.');$v=trim($v);if(strlen($v)>$max*4)fail('Mətn çox uzundur.');if(preg_match('//u',$v)!==1)fail('Mətn UTF-8 olmalıdır.');return $v;}
function localized(mixed $v,int $max=1000,bool $required=false): array {if(!is_array($v))fail('Üçdilli məlumat düzgün deyil.');$r=[];foreach(['az','en','ru']as$l){$r[$l]=text($v[$l]??'',$max);if($required&&$r[$l]==='')fail('Hər üç dildə başlıq tələb olunur.');}return $r;}
function pathValue(mixed $v): string {$v=text($v??'',500);if($v!==''&&!preg_match('~^/?(?:assets|media)/[A-Za-z0-9_./-]+\.(?:webp|png|jpe?g|pdf|svg)$~i',$v))fail('Yalnız saytın media faylını seçin.');if(str_contains($v,'..'))fail('Fayl yolu düzgün deyil.');return ltrim($v,'/');}
function slug(mixed $s): string {$s=text($s,100);if(!preg_match('/^[a-z0-9][a-z0-9-]{1,79}$/D',$s))fail('Ünvan 2–80 kiçik latın hərfi, rəqəm və defisdən ibarət olmalıdır.');return $s;}
function cents(mixed $n): int {$v=(string)$n;if(!preg_match('/^\d{1,9}(?:\.\d{1,2})?$/D',$v))fail('Qiyməti müsbət rəqəmlə yazın, məsələn 1250.50.');[$a,$b]=array_pad(explode('.',$v,2),2,'');return (int)$a*100+(int)str_pad($b,2,'0');}
function clean(string $kind,array $d): array {
    $out=[];
    if(in_array($kind,['category','product','brand','article','page'],true)){
        $out['name']=localized($d['name']??[],180,true);$out['description']=localized($d['description']??[],5000);
        $out['image']=pathValue($d['image']??'');$out['image_alt']=localized($d['image_alt']??[],250);
        $out['seo_title']=localized($d['seo_title']??[],180);$out['seo_description']=localized($d['seo_description']??[],500);
        $out['slug']=slug($d['slug']??$d['id']??'');
    }
    if($kind==='category'){$out['group']=$d['group']??'';if(!in_array($out['group'],['workplace','infrastructure','security','collaboration','software'],true))fail('Kateqoriya qrupu düzgün deyil.');$out['icon']=preg_replace('/[^a-z-]/','',(string)($d['icon']??'computer'));$out['products']=[];foreach(array_slice($d['products']??[],0,40)as$p)$out['products'][]=localized($p,200,true);}
    elseif($kind==='product'){$out['category']=text($d['category']??'',80);$out['brand']=text($d['brand']??'',120);$out['model']=text($d['model']??'',180);$out['part_number']=text($d['part_number']??'',180);$out['availability']=$d['availability']??'on_request';if(!in_array($out['availability'],['in_stock','to_order','on_request'],true))fail('Mövcudluq düzgün deyil.');$out['price']=($d['price']??'')===''?'':number_format(cents($d['price'])/100,2,'.','');$out['currency']=$d['currency']??'AZN';if(!in_array($out['currency'],['AZN','USD','EUR'],true))fail('Valyuta düzgün deyil.');$out['document']=pathValue($d['document']??'');$out['specs']=localized($d['specs']??[],12000);}
    elseif($kind==='brand'){$out['featured']=!empty($d['featured']);$out['group']=max(0,min(count(seed()['brandGroups'])-1,(int)($d['group']??0)));}
    elseif(in_array($kind,['article','page'],true)){$out['body']=localized($d['body']??[],24000);$out['slots']=[];if($kind==='page'){foreach(['az','en','ru']as$l){$out['slots'][$l]=[];foreach(array_slice($d['slots'][$l]??[],0,250)as$slot){if(!preg_match('/^t[0-9]+$/D',(string)($slot['id']??'')))fail('Mətn sahəsi düzgün deyil.');$out['slots'][$l][]=['id'=>$slot['id'],'tag'=>text($slot['tag']??'p',10),'text'=>text($slot['text']??'',12000)];}}$out['paths']=$d['paths']??[];foreach($out['paths']as$p)if(!preg_match('~^(?:[a-z0-9-]+/)?[a-z0-9.-]+\.html$~D',$p))fail('Səhifə yolu düzgün deyil.');}}
    elseif($kind==='company'){$out=['name'=>text($d['name']??'',180),'email'=>text($d['email']??'',180),'phone'=>text($d['phone']??'',40),'displayPhone'=>text($d['displayPhone']??'',60),'linkedin'=>text($d['linkedin']??'',500),'instagram'=>text($d['instagram']??'',500),'address'=>text($d['address']??'',500),'tax_number'=>text($d['tax_number']??'',60),'logo'=>pathValue($d['logo']??''),'whatsapp_phone'=>text($d['whatsapp_phone']??$d['phone']??'',40)];if(!filter_var($out['email'],FILTER_VALIDATE_EMAIL))fail('E-poçt düzgün deyil.');if(!preg_match('/^\+?\d{7,16}$/D',$out['whatsapp_phone']))fail('WhatsApp nömrəsi düzgün deyil.');if(!preg_match('/^\+?\d{7,16}$/D',$out['phone']))fail('Telefon düzgün deyil.');foreach(['linkedin','instagram']as$f)if($out[$f]!==''&&(!filter_var($out[$f],FILTER_VALIDATE_URL)||parse_url($out[$f],PHP_URL_SCHEME)!=='https'))fail('Sosial keçid HTTPS olmalıdır.');}
    elseif(in_array($kind,['customer','supplier'],true)){$out=['company'=>text($d['company']??'',180),'person'=>text($d['person']??'',120),'contact'=>text($d['contact']??'',180),'notes'=>text($d['notes']??'',6000)];if($out['company']==='')fail('Şirkət adını yazın.');}
    elseif($kind==='request'){$out=['company'=>text($d['company']??'',180),'person'=>text($d['person']??'',120),'contact'=>text($d['contact']??'',180),'details'=>text($d['details']??'',6000),'part_number'=>text($d['part_number']??'',180),'status'=>$d['status']??'new','notes'=>text($d['notes']??'',6000),'items'=>array_slice($d['items']??[],0,100),'language'=>$d['language']??'az'];if(!in_array($out['status'],['new','clarification','sourcing','quoted','confirmed','completed','closed'],true))fail('Sorğu statusu düzgün deyil.');}
    elseif($kind==='quote'){$out=['customer'=>text($d['customer']??'',200),'contact'=>text($d['contact']??'',180),'request_id'=>text($d['request_id']??'',40),'currency'=>$d['currency']??'AZN','valid_until'=>text($d['valid_until']??'',10),'delivery'=>text($d['delivery']??'',1000),'warranty'=>text($d['warranty']??'',1000),'terms'=>text($d['terms']??'',3000),'tax_note'=>text($d['tax_note']??'',600),'status'=>$d['status']??'draft','items'=>[],'total_cents'=>0];if(!in_array($out['currency'],['AZN','USD','EUR'],true)||!in_array($out['status'],['draft','sent','accepted','closed'],true))fail('Təklif məlumatı düzgün deyil.');if($out['valid_until']!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$out['valid_until']))fail('Tarix düzgün deyil.');foreach(array_slice($d['items']??[],0,100)as$i){$qty=filter_var($i['quantity']??0,FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>100000]]);if(!$qty)fail('Məhsul sayı düzgün deyil.');$p=cents($i['price']??'0');if($qty*$p>9000000000000000||$out['total_cents']+$qty*$p>9000000000000000)fail('Təklifin məbləği icazə verilən aralıqdan böyükdür.');$out['items'][]=['name'=>text($i['name']??'',300),'part_number'=>text($i['part_number']??'',180),'quantity'=>$qty,'price_cents'=>$p,'line_cents'=>$qty*$p];$out['total_cents']+=$qty*$p;}if(!$out['items'])fail('Təklifə məhsul əlavə edin.');}
    else fail('Bölmə düzgün deyil.');
    if($kind==='request'){$items=[];foreach($out['items']as$i){if(!is_array($i))fail('Məhsul siyahısı düzgün deyil.');$q=filter_var($i['quantity']??1,FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>100000]]);if(!$q)fail('Məhsul sayı düzgün deyil.');$items[]=['name'=>text($i['name']??'',300),'quantity'=>$q];}$out['items']=$items;}
    return $out;
}
const CONTENT=['category','product','brand','article','page','company'];
function publicPaths(string $kind,array $data): array {$stem=match($kind){'category'=>'products/'.$data['slug'],'product'=>'products/item-'.$data['slug'],'article'=>'articles/'.$data['slug'],default=>null};return $stem?array_map(fn($lang)=>$stem.($lang==='az'?'':'.'.$lang).'.html',['az','en','ru']):[];}
function checkPublicPaths(array $r): void {$paths=publicPaths($r['kind'],$r['data']);if(!$paths)return;foreach(seed()['routes']as$route)if($route['record']!==$r['id']&&in_array($route['file'],$paths,true))fail('Bu səhifə ünvanı artıq istifadə olunur.',409);foreach(query("SELECT id,kind,published FROM records WHERE published IS NOT NULL AND archived=0")as$other)if($other['id']!==$r['id']&&array_intersect($paths,publicPaths($other['kind'],json_decode($other['published'],true))))fail('Bu səhifə ünvanı artıq istifadə olunur.',409);}
function record(string $id): array {$r=query('SELECT * FROM records WHERE id=?',[$id])->fetch();if(!$r)fail('Qeyd tapılmadı.',404);$r['data']=json_decode($r['data'],true);$r['published']=$r['published']?json_decode($r['published'],true):null;$r['revision']=(int)$r['revision'];return $r;}
function audit(string $actor,string $action,string $entity): void {query('INSERT INTO audit(id,actor,action,entity,created_at) VALUES(?,?,?,?,?)',[uuid(),$actor,$action,$entity,now()]);}
function saveRecord(string $id,string $kind,array $data,int $revision,array $actor): array {
    $d=clean($kind,$data);$json=json_encode($d,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG);$pdo=db();$owns=!$pdo->inTransaction();if($owns)$pdo->beginTransaction();
    try{$old=query('SELECT * FROM records WHERE id=?',[$id])->fetch();if($old){if((int)$old['revision']!==$revision)fail('Qeyd başqa yerdə dəyişdirilib. Yeniləyib təkrar yoxlayın.',409);if($old['kind']!==$kind)fail('Qeydin növü dəyişdirilə bilməz.');$pub=$old['published']?json_decode($old['published'],true):null;if($pub&&isset($pub['slug'])&&($pub['slug']!==($d['slug']??'')))fail('Yayımlanmış ünvan dəyişdirilə bilməz.');if($kind==='page'&&$pub&&($pub['paths']??[])!==($d['paths']??[]))fail('Səhifənin əsas ünvanları qorunur.');query('INSERT INTO revisions(id,record_id,data,created_by,created_at) VALUES(?,?,?,?,?)',[uuid(),$id,$old['data'],$actor['email'],now()]);query('UPDATE records SET data=?,revision=revision+1,updated_at=?,updated_by=? WHERE id=? AND revision=?',[$json,now(),$actor['email'],$id,$revision]);}else{query('INSERT INTO records(id,kind,data,published,revision,archived,updated_at,updated_by) VALUES(?,?,?,NULL,1,0,?,?)',[$id,$kind,$json,now(),$actor['email']]);}audit($actor['email'],'save',$kind.':'.$id);if($owns)$pdo->commit();}catch(\Throwable$e){if($owns&&$pdo->inTransaction())$pdo->rollBack();throw$e;}return record($id);
}
function published(string $kind): array {$s=query('SELECT id,published FROM records WHERE kind=? AND archived=0 AND published IS NOT NULL ORDER BY updated_at,id',[$kind]);$out=[];foreach($s as$r){$d=json_decode($r['published'],true);$d['id']=$r['id'];$out[]=$d;}return $out;}
function setupKey(): string {$f=privateDir().'/setup-key.txt';if(!is_file($f)){ $h=@fopen($f,'x');if($h){chmod($f,0600);fwrite($h,bin2hex(random_bytes(24)));fclose($h);} }return trim((string)file_get_contents($f));}
function install(array $d): void {
    if(config())fail('Panel artıq quraşdırılıb.',409);$lock=fopen(privateDir().'/install.lock','c');if(!$lock||!flock($lock,LOCK_EX))fail('Quraşdırma hazır deyil.',503);
    try{if(config())fail('Panel artıq quraşdırılıb.',409);if(!hash_equals(setupKey(),(string)($d['setup_key']??'')))fail('Quraşdırma açarı yanlışdır.',403);
    $email=text($d['email']??'',180);$name=text($d['name']??'',120);$password=(string)($d['password']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<12||strlen($password)>200)fail('E-poçt və ən azı 12 simvolluq şifrə yazın.');
    $engine=$d['engine']??'sqlite';if($engine==='mysql'){$host=text($d['db_host']??'localhost',180);$database=text($d['db_name']??'',120);if(!preg_match('/^[a-zA-Z0-9_.-]+$/D',$host)||!preg_match('/^[a-zA-Z0-9_]+$/D',$database))fail('Verilənlər bazası məlumatı düzgün deyil.');$cfg=['dsn'=>"mysql:host=$host;dbname=$database;charset=utf8mb4",'db_user'=>text($d['db_user']??'',180),'db_password'=>(string)($d['db_password']??'')];}elseif($engine==='sqlite'){$cfg=['dsn'=>'sqlite:'.privateDir().'/norda.sqlite'];}else fail('Verilənlər bazası növü düzgün deyil.');
    $pdo=new \PDO($cfg['dsn'],$cfg['db_user']??null,$cfg['db_password']??null,[\PDO::ATTR_ERRMODE=>\PDO::ERRMODE_EXCEPTION]);
    $driver=$pdo->getAttribute(\PDO::ATTR_DRIVER_NAME);foreach([
      'CREATE TABLE IF NOT EXISTS users(id VARCHAR(40) PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,name VARCHAR(200) NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL,disabled INTEGER NOT NULL DEFAULT 0,created_at VARCHAR(30) NOT NULL)',
      'CREATE TABLE IF NOT EXISTS records(id VARCHAR(40) PRIMARY KEY,kind VARCHAR(30) NOT NULL,data MEDIUMTEXT NOT NULL,published MEDIUMTEXT NULL,revision INTEGER NOT NULL DEFAULT 1,archived INTEGER NOT NULL DEFAULT 0,updated_at VARCHAR(30) NOT NULL,updated_by VARCHAR(190) NOT NULL)',
      'CREATE TABLE IF NOT EXISTS revisions(id VARCHAR(40) PRIMARY KEY,record_id VARCHAR(40) NOT NULL,data MEDIUMTEXT NOT NULL,created_by VARCHAR(190) NOT NULL,created_at VARCHAR(30) NOT NULL)',
      'CREATE TABLE IF NOT EXISTS audit(id VARCHAR(40) PRIMARY KEY,actor VARCHAR(190) NOT NULL,action VARCHAR(40) NOT NULL,entity VARCHAR(150) NOT NULL,created_at VARCHAR(30) NOT NULL)',
      'CREATE TABLE IF NOT EXISTS files(id VARCHAR(40) PRIMARY KEY,record_id VARCHAR(40) NOT NULL,original_name VARCHAR(255) NOT NULL,stored_name VARCHAR(100) NOT NULL,mime VARCHAR(100) NOT NULL,size_bytes INTEGER NOT NULL,created_at VARCHAR(30) NOT NULL)'
    ]as$sql)$pdo->exec($sql.($driver==='mysql'?' CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci':''));
    $pdo->beginTransaction();$u=$pdo->prepare('INSERT INTO users(id,email,name,password_hash,role,disabled,created_at) VALUES(?,?,?,?,?,0,?)');$u->execute([uuid(),strtolower($email),$name,password_hash($password,PASSWORD_DEFAULT),'owner',now()]);$insert=$pdo->prepare('INSERT INTO records(id,kind,data,published,revision,archived,updated_at,updated_by) VALUES(?,?,?,?,1,0,?,?)');foreach(seed()['records']as$r){$data=json_encode($r['data'],JSON_UNESCAPED_UNICODE|JSON_HEX_TAG);$insert->execute([$r['id'],$r['kind'],$data,$data,now(),$email]);}$pdo->commit();$cfg['salt']=bin2hex(random_bytes(32));$tmp=privateDir().'/config-'.uuid().'.php';file_put_contents($tmp,"<?php\nreturn ".var_export($cfg,true).";\n",LOCK_EX);chmod($tmp,0600);rename($tmp,privateDir().'/config.php');@unlink(privateDir().'/setup-key.txt');
    }finally{flock($lock,LOCK_UN);fclose($lock);}
}
function rate(string $scope,int $max,int $seconds): void {$salt=config()['salt']??'setup';$key=hash('sha256',$scope.'|'.($_SERVER['REMOTE_ADDR']??'unknown').'|'.$salt);$dir=privateDir().'/limits';if(!is_dir($dir))mkdir($dir,0700,true);$f=fopen($dir.'/'.$key,'c+');flock($f,LOCK_EX);$a=json_decode(stream_get_contents($f)?:'[]',true)?:[];$a=array_values(array_filter($a,fn($t)=>$t>time()-$seconds));if(count($a)>=$max){flock($f,LOCK_UN);fclose($f);fail('Çox sorğu göndərilib. Bir qədər sonra təkrar yoxlayın.',429);}$a[]=time();ftruncate($f,0);rewind($f);fwrite($f,json_encode($a));flock($f,LOCK_UN);fclose($f);}
function upload(array $f,string $recordId,bool $public=false): array {
    if(($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)fail('Fayl yüklənmədi.');if($f['size']>($public?5000000:10000000))fail('Fayl çox böyükdür.',413);
    $mime=(new \finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));
    if($public){$allow=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','application/pdf'=>'pdf'];if(!isset($allow[$mime]))fail('JPG, PNG, WebP və ya PDF faylı seçin.');if($mime!=='application/pdf'){ $dims=@getimagesize($f['tmp_name']);if(!$dims||$dims[0]*$dims[1]>25000000)fail('Şəklin ölçüsü çox böyükdür.');}$ext=$allow[$mime];$dir=dirname(__DIR__,2).'/media';}
    else {if($ext==='pdf'){if($mime!=='application/pdf')fail('PDF faylı düzgün deyil.');}elseif($ext==='csv'){if(!str_starts_with($mime,'text/')&&$mime!=='application/csv')fail('CSV faylı düzgün deyil.');}elseif($ext==='xlsx'){if(!class_exists('ZipArchive'))fail('XLSX üçün ZIP modulu aktiv olmalıdır. PDF və CSV istifadə edə bilərsiniz.');$z=new \ZipArchive();if($z->open($f['tmp_name'])!==true||$z->locateName('xl/workbook.xml')===false||$z->numFiles>2000)fail('XLSX faylı düzgün deyil.');$z->close();}else fail('Yalnız PDF, CSV və XLSX faylları qəbul edilir.');$dir=privateDir().'/attachments';}
    if(!is_dir($dir))mkdir($dir,0750,true);$name=uuid().'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))fail('Fayl saxlanmadı.',500);$id=uuid();$original=substr(basename(str_replace('\\','/',$f['name'])),0,220);query('INSERT INTO files(id,record_id,original_name,stored_name,mime,size_bytes,created_at) VALUES(?,?,?,?,?,?,?)',[$id,$recordId,$original,$name,$mime,$f['size'],now()]);return ['id'=>$id,'name'=>$original,'url'=>$public?'media/'.$name:null,'size'=>$f['size']];
}
